import{_ as i,o as e,c as a,a2 as r}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"申请要求","description":"","frontmatter":{},"headers":[],"relativePath":"interview/require.md","filePath":"interview/require.md","lastUpdated":null}'),t={name:"interview/require.md"};function o(n,l,h,s,c,u){return e(),a("div",null,[...l[0]||(l[0]=[r('<h1 id="申请要求" tabindex="-1">申请要求 <a class="header-anchor" href="#申请要求" aria-label="Permalink to &quot;申请要求&quot;">​</a></h1><h2 id="申请渠道" tabindex="-1">申请渠道 <a class="header-anchor" href="#申请渠道" aria-label="Permalink to &quot;申请渠道&quot;">​</a></h2><ul><li><a href="https://angel.co/jobs" target="_blank" rel="noreferrer">https://angel.co/jobs</a></li><li><a href="https://www.kanzhun.com/" target="_blank" rel="noreferrer">https://www.kanzhun.com/</a></li></ul><h2 id="硬性要求" tabindex="-1">硬性要求 <a class="header-anchor" href="#硬性要求" aria-label="Permalink to &quot;硬性要求&quot;">​</a></h2><p>硬性要求是指马上就能甄别出来的，比如：</p><ul><li>学历要求：一般要求是专科，有一些公司也要求必须是本科，甚至是985、211，学历一般要求很难伪装或造假，不然后果很严重，你们懂的。</li><li>专业要求：中文、市场营销、电子商务、计算机科学与技术（优先）等都可以；</li><li>工作年限：一般一年起的工作经验就行，但是必须是互联网相关经验，最好是产品经理实习经验和工作经验。三年工作经验的童鞋不一定在面试中有多大优势。白纸有的时候还是更大优势的，因为白纸可以由用人方通过公司内部培训定制其工作能力，比某些有经验的求职者更容易驾驭。</li></ul><h2 id="能力要求" tabindex="-1">能力要求 <a class="header-anchor" href="#能力要求" aria-label="Permalink to &quot;能力要求&quot;">​</a></h2><p>能力要求，比如对某类产品的了解程度、对工作中需要使用的软件工具的熟悉程度等。</p><ul><li>熟练使用Visio、Project、Axure、OmniGraffle等软件独立完成产品PRD文档、Demo制作及MRD撰写；</li><li>具备熟练的数据分析，总结能力，能够通过各种运营数据的收集，归纳，分析对产品的设计和运营进行及时的调整及改进；</li><li>有产品意识、用户意识；</li><li>各种软能力，比如自我管理能力、逻辑思维、沟通学习能力、抗压能力等。<a href="https://zhuanlan.zhihu.com/p/25821858" target="_blank" rel="noreferrer">1</a></li></ul><h2 id="黑话" tabindex="-1">黑话 <a class="header-anchor" href="#黑话" aria-label="Permalink to &quot;黑话&quot;">​</a></h2><ol><li>能承受较大的工作压力——加班</li><li>抗压能力强——加班+替别人扛雷</li><li>工作有激情——自觉加班还要特美</li><li>有强烈责任心——没做完不准走</li><li>弹性工作制——加班不给加班费</li><li>弹性工作制，但不保证准时下班——做完了才准走</li><li>包三餐——早晚都得加班</li><li>双休——工作日加班</li><li>薪资+社保+带薪休假+职位晋升——是个正经公司都有，没什么拿得出手的福利</li><li>适应较快的工作节奏——加班把三天的工作两天做完</li><li>公司提供水果——貌似也就这一个福利</li><li>有强烈的上进心——干完工作就加班去干其他工作</li><li>喜欢有挑战性的工作——加班、前人留的坑不少</li><li>不提倡加班——你懂的（该加还得加，加班是因为你工作效率低，不是安排工作多）</li><li>不强制加班——你懂的 （不做完额外安排的工作你走一个试试！）</li><li>上不封顶——下不保底</li><li>偶尔会忙——以后忙了你别抱怨，提醒过了</li><li>团队氛围很好——大家经常一起加班，一起吃加班餐，聊聊工作，多happy</li><li>上升空间大——工资低，3000元涨个50%不也就4500吗？</li><li>领导安排的其它任务——我叫你干啥你就得干啥</li><li>妹子多——这个屌丝虽然脑子不太好使但便宜，看看这个理由能不能骗一蛤</li><li>有期权——没多余的现金发工资给你</li><li>有股权——工资微妙地低于你应得的数，反正我不信你能干满拿走</li><li>年底双薪——13 薪</li><li>13 薪起——别想了，就是13 薪</li><li>年底有奖金——年薪大于 12 薪小于 13 薪</li><li>我们 6 点准时下班 -——入职才知道最严重的早晨 6 点下班，回家吃早饭睡觉。</li><li>扁平化管理 -——领导和你坐一屋，盯着你干活</li><li>核心团队来自 bat ——嗯，你不是bat的，所以你不是核心</li><li>我把你的简历整理一下——对方说这个的话基本可以判断他是卖人头外派的了,把你的简历给他的甲方.</li><li>弹性工作时间——只弹下班，不弹上班</li><li>能独立完成任务 ——产品测试推广运营全都你一个人干</li><li>配发笔记本——晚上回家也别想闲着</li><li>欧美创业环境——比798破一万倍的大厂房</li><li>管吃管住——除了工作就是宿舍，宿舍就在公司的另外一个角落</li><li>妹子多——有些<a href="https://www.bilibili.com/video/BV1be411s77M?from=search&amp;seid=1121008457557507583" target="_blank" rel="noreferrer">2</a></li></ol>',11)])])}const _=i(t,[["render",o]]);export{p as __pageData,_ as default};
